package android.content;import android.media.session.*;import java.util.*;public class Context {public static final String MEDIA_SESSION_SERVICE="media_session";public final MediaSessionManager manager=new MediaSessionManager();public final List<Intent> broadcasts=new ArrayList<>();public final java.util.concurrent.CopyOnWriteArrayList<BroadcastReceiver> receivers=new java.util.concurrent.CopyOnWriteArrayList<>();public String receiverPermission;public Intent registerReceiver(BroadcastReceiver r,IntentFilter f,String permission,android.os.Handler h){receivers.add(r);receiverPermission=permission;return null;}public void unregisterReceiver(BroadcastReceiver r){receivers.remove(r);}public void deliver(Intent i){for(BroadcastReceiver r:receivers)r.onReceive(this,i);}public Context getApplicationContext(){return this;}public Object getSystemService(String s){return manager;}public void sendBroadcast(Intent i,String p){broadcasts.add(i);}}
